begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id) values ('50000000-0000-0000-0000-000000000005'),('60000000-0000-0000-0000-000000000006');
select lives_ok($$select public.save_mock_dream('50000000-0000-0000-0000-000000000005','51000000-0000-0000-0000-000000000005','{"transcript":"Unuttum.","inputMode":"text","dreamDate":"2026-10-10","timezone":"UTC","locale":"tr"}','{"image_prompt":"Anonymous","interpretations":{"neuroscience":"General","jungian":"Question","astrological":"Symbolic"},"tags":[]}',null,null)$$,'Sparse report allows zero tags');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"50000000-0000-0000-0000-000000000005","role":"authenticated"}',true);
select ok(not has_function_privilege('authenticated','public.revise_dream(uuid,uuid,text,integer)','EXECUTE'),'Clients cannot bypass revision API');
select ok(not has_function_privilege('authenticated','public.save_dream_journal(uuid,uuid,jsonb)','EXECUTE'),'Clients cannot bypass journal validation');
select ok(not has_function_privilege('authenticated','public.review_dream_observation(uuid,uuid,integer,boolean,integer)','EXECUTE'),'Clients cannot forge observation reviews');
select throws_ok($$update public.dreams set content_report='{}'$$,'42501',null,'Clients cannot forge grounded reports');
select throws_ok($$update public.dreams set journal='{}'$$,'42501',null,'Clients cannot forge journal persistence');
reset role;
select throws_ok($$select public.revise_dream('60000000-0000-0000-0000-000000000006','51000000-0000-0000-0000-000000000005','Forbidden',1)$$,'P0001','NOT_FOUND','Revision checks ownership');
select lives_ok($$select public.revise_dream('50000000-0000-0000-0000-000000000005','51000000-0000-0000-0000-000000000005','Korktum.',1)$$,'Owner revises current transcript');
select is((select transcript_revision from public.dreams where id='51000000-0000-0000-0000-000000000005'),2,'Revision increments once');
select ok((select status='draft' and content_report is null and image_path is null and neuroscience_interpretation is null from public.dreams where id='51000000-0000-0000-0000-000000000005'),'Correction clears old derived fields');
select throws_ok($$select public.revise_dream('50000000-0000-0000-0000-000000000005','51000000-0000-0000-0000-000000000005','Stale',1)$$,'P0001','REVISION_CONFLICT','Stale correction cannot replace current text');
select lives_ok($$select public.confirm_dream_event('50000000-0000-0000-0000-000000000005','51000000-0000-0000-0000-000000000005',2)$$,'Owner can confirm separate event');
select ok((select event_confirmed from public.dreams where id='51000000-0000-0000-0000-000000000005'),'Event decision persists');
select * from finish();
rollback;
